require_once 'config.php';$email=$_SESSION['reset_email']??'';if($email===''){header('Location: '.$base_url.'quen-mat-khau');exit;}$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_guard();$otp=trim($_POST['otp']??'');$password=(string)($_POST['password']??'');$confirm=(string)($_POST['confirm_password']??'');if(!preg_match('/^\d{6}$/',$otp)||strlen($password)<6||$password!==$confirm){$error='OTP hoặc mật khẩu mới chưa hợp lệ.';}else{$stmt=$conn->prepare('SELECT id FROM users WHERE email=? LIMIT 1');$stmt->bind_param('s',$email);$stmt->execute();$user=$stmt->get_result()->fetch_assoc();$stmt->close();if($user){$stmt=$conn->prepare('SELECT * FROM password_resets WHERE user_id=? AND used_at IS NULL ORDER BY id DESC LIMIT 1');$stmt->bind_param('i',$user['id']);$stmt->execute();$reset=$stmt->get_result()->fetch_assoc();$stmt->close();if($reset&&strtotime($reset['expires_at'])>=time()&&(int)$reset['attempts']<5&&password_verify($otp,$reset['token_hash'])){$new=password_hash_secure($password);$conn->begin_transaction();$stmt=$conn->prepare('UPDATE users SET password=? WHERE id=?');$stmt->bind_param('si',$new,$user['id']);$stmt->execute();$stmt->close();$stmt=$conn->prepare('UPDATE password_resets SET used_at=NOW() WHERE id=?');$stmt->bind_param('i',$reset['id']);$stmt->execute();$stmt->close();$conn->commit();unset($_SESSION['reset_email']);$_SESSION['auth_success']='Mật khẩu đã được cập nhật. Bạn có thể đăng nhập.';header('Location: '.$base_url.'dang-nhap');exit;}if($reset){$stmt=$conn->prepare('UPDATE password_resets SET attempts=attempts+1 WHERE id=?');$stmt->bind_param('i',$reset['id']);$stmt->execute();$stmt->close();}}$error='Mã OTP không đúng hoặc đã hết hạn.';}}
include 'header.php';$masked=preg_replace('/(^.).*(@.*$)/','$1***$2',$email);
?>
